#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_geo_flow.py — Kit 29 (Geo Flow: GeoIP → 250 → listV2 → freightCalculateTip)
=================================================================================
يخدم من جذر المشروع — كيتعرف على الشجرة وحدو:
  · backend  (فيه server.js)  → lib/geoCountry.js + data/cjCountries.json
                                + routes/cjLiveBridge.js (تعويض كامل)
                                + لصقة shipOverrideUsd فـ services/productImportService.js
  · frontend (فيه next.config.ts) → cj-search/page.tsx + cj-product/[pid]/page.tsx

Backup تلقائي: *.bak-kit29 (أول مرة فقط — ما كيتغطاش backup قديم).
الأنكورات مفحوصين — إلا تبدلو: إيقاف بلا حتى تعديل (safe).
"""
import base64, os, shutil, sys

BACKUP = ".bak-kit29"
B = lambda name: base64.b64decode(FILES[name]).decode("utf-8")

FILES = {"backend/lib/geoCountry.js": "", "backend/data/cjCountries.json": "", "backend/routes/cjLiveBridge.js": "", "frontend/cj-search-page.tsx": "", "frontend/cj-product-page.tsx": ""}

# ── لصقة التسعير — shipOverrideUsd (توافقي خلفي 100%) ──
PRICE_ANCHOR_OLD = """function calculateSellingPrice(cjPrice, weightGrams = 0) {
  const cost = parseMaxNumber(cjPrice);
  if (cost <= 0) return { safePrice: PRICE_FLOOR(), safeOriginalPrice: null };

  const ship = estimateShipUsd(weightGrams);
  const landed = cost + ship;"""
PRICE_ANCHOR_NEW = """// \U0001F195 Geo Flow v3.0 \u2014 shipOverrideUsd (\u0627\u062e\u062a\u064a\u0627\u0631\u064a): \u0627\u0644\u0634\u062d\u0646 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0645\u0646 freightCalculateTip.
// null/0 \u2192 \u0627\u0644\u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0642\u062f\u064a\u0645 (estimateShipUsd) \u2014 \u0627\u0644\u062a\u0648\u0627\u0641\u0642\u064a\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 100% \u0645\u0639 \u0643\u0644 \u0627\u0644\u0645\u0633\u062a\u062f\u0639\u064a\u0646.
function calculateSellingPrice(cjPrice, weightGrams = 0, shipOverrideUsd = null) {
  const cost = parseMaxNumber(cjPrice);
  if (cost <= 0) return { safePrice: PRICE_FLOOR(), safeOriginalPrice: null };

  const override = Number(shipOverrideUsd);
  const ship = (override > 0 && isFinite(override)) ? override : estimateShipUsd(weightGrams);
  const landed = cost + ship;"""

def backup(path):
    bak = path + BACKUP
    if not os.path.exists(bak):
        shutil.copy2(path, bak)
        return f"backup → {os.path.basename(bak)}"
    return "backup موجود مسبقاً (محفوظ)"

def write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)

def detect_tree():
    if os.path.exists("server.js") and os.path.exists("routes"):
        return "backend"
    if os.path.exists("next.config.ts") or os.path.exists("next.config.js"):
        return "frontend"
    return None

def install_backend():
    print("── BACKEND ──")
    # 1. الجديد
    write("lib/geoCountry.js", B("backend/lib/geoCountry.js"))
    print("  ✚ lib/geoCountry.js (جديد)")
    write("data/cjCountries.json", B("backend/data/cjCountries.json"))
    print("  ✚ data/cjCountries.json (سجل CJ الـ 250 — مع تصحيح DR Congo→CD)")
    # 2. تعويض الـ bridge
    p = "routes/cjLiveBridge.js"
    if os.path.exists(p):
        print("  ♻ " + backup(p))
    else:
        print("  ⚠ cjLiveBridge.js غير موجود — غادي يتصاوب جديد")
    write(p, B("backend/routes/cjLiveBridge.js"))
    print("  ✚ routes/cjLiveBridge.js (v3.0 GEO — listV2 + freightCalculateTip)")
    # 3. لصقة التسعير
    p = "services/productImportService.js"
    if not os.path.exists(p):
        print("  ❌ services/productImportService.js مفقود — لصقة التسعير توقفت"); return False
    src = open(p, encoding="utf-8").read()
    if "shipOverrideUsd" in src:
        print("  ✓ productImportService.js — shipOverrideUsd موجودة مسبقاً (skip)")
    elif PRICE_ANCHOR_OLD in src:
        print("  ♻ " + backup(p))
        write(p, src.replace(PRICE_ANCHOR_OLD, PRICE_ANCHOR_NEW, 1))
        print("  ✚ لصقة shipOverrideUsd نجحت (توافقي خلفي)")
    else:
        print("  ❌ الأنكور ديال calculateSellingPrice تبدل — لصقة موقفة بلا تعديل. قارن مع services/productImportService.js.bak-kit29"); return False
    print("  [NEXT] restart الـ backend (Render redeploy أو node server.js)")
    return True

def install_frontend():
    print("── FRONTEND ──")
    p1 = "app/cj-search/page.tsx"
    p2 = os.path.join("app", "cj-product", "[pid]", "page.tsx")
    for p in (p1, p2):
        if os.path.exists(p):
            print("  ♻ " + backup(p))
    write(p1, B("frontend/cj-search-page.tsx"))
    print("  ✚ " + p1 + " (chip البلد من geo)")
    write(p2, B("frontend/cj-product-page.tsx"))
    print("  ✚ " + p2 + " (الثمن المباشر shipping cj-live)")
    print("  [NEXT] npm run build (لازم يعدّ بلا أخطاء) ثم deploy")
    return True

tree = detect_tree()
if tree == "backend":
    ok = install_backend()
elif tree == "frontend":
    ok = install_frontend()
else:
    print("❌ خدم من جذر المشروع (المجلد اللي فيه server.js للـ backend / next.config.ts للـ frontend)")
    sys.exit(1)
sys.exit(0 if ok else 1)
